 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The underlying picture is a horizontally repeating row. Recover each
    # column's background color by its most frequent visible value.
    base = []
    for c in range(w):
        counts = Counter(grid[r][c] for r in range(h) if grid[r][c] != 0)
        base.append(counts.most_common(1)[0][0] if counts else 0)

    # Find the smallest repeating period in the recovered background row.
    period = w
    for p in range(1, w + 1):
        if all(base[c] == base[c % p] for c in range(w)):
            period = p
            break

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r == c:
                    out[r][c] = base[(c - 1) % period]
                else:
                    out[r][c] = base[c]
    return out
